{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.sku_group_sample_to_live as ( with stl as(with live_date_pre as ( select CASE WHEN REGEXP_COUNT(value:sku::STRING, \'-\') >= 2 THEN LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) ELSE value:sku::STRING END AS sku_group, min(PUBLISHEDAT::date) as live_date, min(CREATEDAT::date) as created_at_date, max(totalinventory) as shopify_actual_inv, lower(status) as status from snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value group by 1,5 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, live_date, created_at_date, shopify_actual_inv, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), live_date as ( select sku_group, status, live_date, created_at_date, shopify_actual_inv from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), inwards AS ( SELECT CASE WHEN REGEXP_COUNT(UPPER(TRIM(\"Item Type skuCode\")), \'-\') >= 2 THEN UPPER(TRIM(REGEXP_REPLACE(\"Item Type skuCode\", \'-[^-]+$\', \'\'))) ELSE UPPER(\"Item Type skuCode\") END AS sku_group, putaway_completed_date AS date, SUM(total_quantity) AS quant FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(final_type) LIKE \'new inward\' AND UPPER(\"Putaway Item Status Code\") LIKE \'COMPLETE\' GROUP BY 1,2 ), catalog as ( select upper(sku_group) as sku_group, Case when upper(sku_group) like \'MP%\' then \'not_in_marketplace\' else \'not_in_shopify\' end as status, min(date) as latest_inward_date, sum(quant) as units_on_hand from inwards where quant > 0 group by 1 ), base_cte AS ( SELECT distinct CASE WHEN UPPER(TRIM(barcode)) LIKE \'MP%\' AND REGEXP_COUNT(UPPER(TRIM(barcode)), \'-\') = 3 THEN UPPER(TRIM(REGEXP_REPLACE(barcode, \'-[^-]+$\', \'\'))) WHEN UPPER(TRIM(barcode)) LIKE \'MP%\' AND REGEXP_COUNT(UPPER(TRIM(barcode)), \'-\') <= 2 THEN UPPER(TRIM(barcode)) WHEN REGEXP_COUNT(UPPER(TRIM(barcode)), \'-\') >= 2 THEN UPPER(TRIM(REGEXP_REPLACE(barcode, \'-[^-]+$\', \'\'))) ELSE UPPER(TRIM(barcode)) END AS sku_group, sku_type as collection, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(sample_received_date_shoot), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS sample_received_ts, MAX(TO_TIMESTAMP_NTZ(FLOOR(TRY_TO_NUMBER(TRIM(edit_complete_time)) / 1000))) AS edit_complete_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(catalogus_sent_time_stamp), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS catalogix_sent_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(catalogus_received_time_stamp), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS catalogix_received_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(production_creation_date), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS production_creation_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(shoot_date), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS scheduled_shoot_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(SAMPLE_DISPATCH_DATE_PRODUCTION), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS SAMPLE_DISPATCH_DATE_PRODUCTION, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(edi_assign_date), \'\'), \'DD-MM-YYYY\')) AS IMAGE_RECIEVED_DATE, MAX(TO_TIMESTAMP_NTZ(FLOOR(TRY_TO_NUMBER(TRIM(NULLIF(catalog_completed_date,\'\'))) / 1000))) AS marketplace_cataloged_ts, MAX(factory) AS factory, MAX(editor_name) AS editor_name, MAX(photoshoot_status) AS photoshoot_status, MAX(image_selection) AS image_selection, MAX(shoot_tags) AS shoot_tags, MAX(production_sku_created_by) AS production_sku_created_by, MAX(NULLIF(shoot_post_remark,\'\')) AS shoot_post_remark, MAX(shoot_type) AS shoot_type from snitch_db.maplemonk.pslj_final_new_pslj_table WHERE TRIM(barcode) IS NOT NULL GROUP BY 1,2 ), sample_received_date AS ( SELECT upper(sku_group) as sku_group, collection as collection, sample_recieved_date FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY sample_recieved_date DESC NULLS LAST ) AS rn FROM ( SELECT DISTINCT UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(sku_group), CHARINDEX(\'-\', REVERSE(sku_group)) + 1, LEN(sku_group))))) AS sku_group, \'null\' as collection, TO_CHAR(TRY_TO_DATE(sample_recieved_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS sample_recieved_date FROM snitch_db.maplemonk.google_Sheet_sample_recieved UNION ALL SELECT upper(sku_group) as sku_group, collection, sample_received_ts::DATE AS sample_recieved_date FROM base_cte) AS combined) AS ranked_sample_received WHERE rn = 1 ), PSLJ AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY edit_received_date DESC NULLS LAST ) AS rn FROM ( SELECT upper(sku) as sku_group, a.\"Factory_\'\", a.selection_ as editor_owner, a.shoot_date as photoshoot_status, a.tagging as IMAGE_SELECTION, TO_CHAR(TRY_TO_DATE(a.owner, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as edit_received_date, TO_CHAR(TRY_TO_DATE(a.editing_status, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as edit_completed_date, TO_CHAR(TRY_TO_DATE(a.final_shared_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as catalogix_sent_timestamp, TO_CHAR(TRY_TO_DATE(a.final_recieved_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as catalogix_received_timestamp, TO_CHAR(TRY_TO_DATE(a.live_on_shopify_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as live_on_shopify_date, NULL marketplace_cataloged_ts, NULL as PRODUCTION_CREATION_DATE, NULL as SAMPLE_DISPATCH_DATE_PRODUCTION, tags as wtw_tags, NULL shoot_type, production_poc from snitch_db.maplemonk.gs_pslj a UNION ALL SELECT upper(sku_group) as sku_group, factory, editor_name AS editor_owner, photoshoot_status, image_selection, TO_CHAR(sample_received_ts, \'YYYY-MM-DD\') AS edit_received_date, TO_CHAR(edit_complete_ts, \'YYYY-MM-DD\') AS edit_completed_date, TO_CHAR(catalogix_sent_ts, \'YYYY-MM-DD\') AS catalogix_sent_timestamp, TO_CHAR(catalogix_received_ts) AS catalogix_received_timestamp, NULL AS live_on_shopify_date, TO_CHAR(marketplace_cataloged_ts, \'YYYY-MM-DD\') AS marketplace_cataloged_ts, TO_CHAR(production_creation_ts, \'YYYY-MM-DD\') AS production_creation_date, TO_CHAR(SAMPLE_DISPATCH_DATE_PRODUCTION,\'YYYY-MM-DD\') AS SAMPLE_DISPATCH_DATE_PRODUCTION, shoot_tags AS wtw_tags, shoot_type, PRODUCTION_SKU_CREATED_BY AS production_poc FROM base_cte ) combined ) ranked_pslj WHERE rn = 1 ), shoot_date AS ( SELECT * FROM ( SELECT DISTINCT UPPER(REGEXP_REPLACE(sku, \'-[^-]+$\', \'\')) AS sku_group, TO_DATE(TRY_TO_DATE(date, \'DD/MM/YYYY\')) AS shoot_date, NULL IMAGE_RECIEVED_DATE FROM snitch_db.maplemonk.gs_shoot_date UNION SELECT DISTINCT upper(sku_group) as sku_group, scheduled_shoot_ts::DATE AS shoot_date, IMAGE_RECIEVED_DATE::DATE as IMAGE_RECIEVED_DATE FROM base_cte ) all_shoots QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY shoot_date DESC NULLS LAST ) = 1 ), RTS AS ( SELECT * FROM ( SELECT upper(sku) as sku_group, CLASS, CASE when upper(sku) like \'MP%\' then \'ready_to_dispatch-MP\' else \'ready_to_dispatch\' END AS status, REPEAT, VENDOR, WAREHOUSE, DESCIPTON, TO_CHAR(TRY_TO_DATE(DELIVEY_DATE_, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS DELIVERY_DATE, COALESCE(TRY_CAST(online_qty AS INT), 0) AS online_qty, QC_STATUS, QC_REPORT, TO_CHAR( COALESCE( TRY_TO_DATE(date_of_entry, \'DD-MM-YYYY\'), TRY_TO_DATE(date_of_entry, \'DD/MM/YYYY\'), TRY_TO_DATE(date_of_entry, \'YYYY-MM-DD\') ), \'YYYY-MM-DD\' ) AS date_of_entry, TO_CHAR( TO_TIMESTAMP_NTZ(FLOOR(TRY_TO_NUMBER(TRIM(last_updated_at)) / 1000)), \'YYYY-MM-DD HH24:MI:SS\' ) AS last_updated_at, TO_CHAR(TRY_TO_DATE(sample_dates, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS sample_dates, \'RTS_GET_RTS_INFO\' AS source_priority FROM snitch_db.maplemonk.new_rts_get_rts_info WHERE repeat = \'NO\' AND UPPER(TRIM(sku)) NOT IN (SELECT sku_group FROM catalog) UNION ALL SELECT upper(sku) as sku_group, CLASS, CASE when upper(sku) like \'MP%\' then \'ready_to_dispatch-MP\' else \'ready_to_dispatch\' END AS status, REPEAT, VENDOR, waehouse, DESCIPTON, TO_CHAR(TRY_TO_DATE(DELIVEY_DATE_, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS DELIVERY_DATE, COALESCE(TRY_CAST(online_qty AS INT), 0) AS online_qty, QC_STATUS, QC_REPORT, NULL AS date_of_entry, NULL AS last_updated_at, NULL AS sample_dates, \'catalog_main\' AS source_priority FROM snitch_db.maplemonk.catalog_main WHERE repeat = \'NO\' AND UPPER(TRIM(sku)) NOT IN (SELECT sku_group FROM catalog) ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY CASE source_priority WHEN \'RTS_GET_RTS_INFO\' THEN 1 WHEN \'catalog_main\' THEN 2 ELSE 3 END ) = 1 ), RTS_delivery_date_fetch AS ( SELECT DISTINCT upper(sku) as sku_group, TO_CHAR(TRY_TO_DATE(DELIVEY_DATE_, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS DELIVERY_DATE_actual, TO_CHAR( COALESCE( TRY_TO_DATE(date_of_entry, \'DD-MM-YYYY\'), TRY_TO_DATE(date_of_entry, \'DD/MM/YYYY\'), TRY_TO_DATE(date_of_entry, \'YYYY-MM-DD\') ), \'YYYY-MM-DD\' ) AS date_of_entry_actual, TO_CHAR( TO_TIMESTAMP_NTZ(FLOOR(TRY_TO_NUMBER(TRIM(last_updated_at)) / 1000)), \'YYYY-MM-DD HH24:MI:SS\' ) AS last_updated_at_actual FROM snitch_db.maplemonk.new_rts_get_rts_info WHERE repeat = \'NO\' ), D2P_metafields_fetch AS ( SELECT DISTINCT sku_group, occassion as d2p_occassion from snitch_db.maplemonk.d2p_tool_transformed_dates ), inventory as ( select upper(sku_group) as sku_group, sellable_inventory as inventory from snitch_db.maplemonk.availability_master_v2 ), main_data as ( select coalesce(a.sku_group,c.SKU_GROUP,r.sku_group) as sku_group, sr.sample_recieved_date::date as sample_received_date, sr.collection, l.live_date::date as live_date, l.created_at_date::date as created_at_date, l.shopify_actual_inv as shopify_actual_inv, a.Photoshoot_Status, sd.shoot_date::date as shoot_date, sd.IMAGE_RECIEVED_DATE, a.edit_received_date, a.editor_owner, a.edit_completed_date, a.catalogix_sent_timestamp, a.catalogix_received_timestamp, a.marketplace_cataloged_ts, a.production_poc, r.delivery_date, r.date_of_entry, r.last_updated_at, ddf.delivery_date_actual, ddf.date_of_entry_actual, ddf.last_updated_at_actual, d2pmf.d2p_occassion, r.sample_dates, a.production_creation_date, a.SAMPLE_DISPATCH_DATE_PRODUCTION, CAST(COALESCE(NULLIF(i.inventory, 0), NULLIF(c.units_on_hand, 0), NULLIF(r.online_qty, 0), 0) AS INTEGER) AS units_on_hand, c.latest_inward_date as inward_date, case when a.sku_group is null and c.sku_group is not null then \'not_in_PSLJ\' else \'present_in_PSLJ\' end as pslj_status, coalesce(l.status,c.status,r.status) as status, DATEDIFF(day, sr.sample_recieved_date, l.live_date) AS sr_live_tat, DATEDIFF(day, sr.sample_recieved_date, sd.shoot_date) AS shoot_tat, datediff(day,sd.shoot_date,a.edit_received_date) as shootdone_editreceived_tat, datediff(day,a.edit_received_date,a.edit_completed_date) as edit_tat, datediff(day,a.edit_completed_date,a.catalogix_sent_timestamp) as editdone_catalogixsent_tat, datediff(day,a.catalogix_sent_timestamp,a.catalogix_received_timestamp) as catalogix_tat, datediff(day,a.catalogix_received_timestamp,l.live_date) as live_tat, a.wtw_tags, a.shoot_type FROM PSLJ a FULL OUTER JOIN catalog c ON a.sku_group = c.sku_group FULL OUTER JOIN RTS r ON COALESCE(a.sku_group, c.SKU_GROUP) = r.sku_group FULL OUTER JOIN live_date l ON COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = l.sku_group left join inventory i on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = i.sku_group left join sample_received_date sr on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = sr.sku_group left join shoot_date sd on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = sd.sku_group left join RTS_delivery_date_fetch ddf on COALESCE(a.sku_group, c.SKU_GROUP) = ddf.sku_group left join D2P_metafields_fetch d2pmf on COALESCE(a.sku_group, c.SKU_GROUP) = d2pmf.sku_group ), main_data2 as ( select *, CASE when sku_group like \'MP%\' and marketplace_cataloged_ts is not null then \'NO_ISSUES\' when lower(status) = \'active\' or live_date is not null then \'NO_ISSUES\' when lower(status) = \'ready_to_dispatch\' and live_date is not null then \'NO_ISSUES\' when lower(status) = \'draft\' and inward_date is not null then \'QC\' when lower(status) = \'draft\' and inward_date is null then \'CATALOG_INWARD_NOT_DONE\' when lower(status) like \'ready_to_dispatch%\' and shoot_date is null and sample_received_date is not null then \'RTS_SHOOT_NOT_DONE\' when lower(status) like \'ready_to_dispatch%\' and shoot_date is not null and (EDIT_RECEIVED_DATE is null or edit_completed_date is null) then \'RTS_EDIT_NOT_DONE\' when lower(status) like \'ready_to_dispatch%\' and shoot_date is not null and edit_completed_date is not null then \'RTS_CATALOG_NOT_DONE\' when lower(status) like \'ready_to_dispatch%\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and CATALOGIX_SENT_TIMESTAMP is not null and catalogix_received_timestamp is not null and inward_date is null then \'RTS_INWARD_NOT_DONE\' when lower(status) like \'ready_to_dispatch%\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and CATALOGIX_SENT_TIMESTAMP is not null and catalogix_received_timestamp is not null and inward_date is not null then \'RTS_QC\' when lower(status) not in (\'active\',\'draft\') and sample_dispatch_date_production is null and sample_received_date is null then \'SAMPLE_NOT_RECEIVED_IN_HQ\' when lower(status) not in (\'active\',\'draft\') and sample_dispatch_date_production is not null and sample_received_date is null then \'SAMPLE_NOT_HANDOVER\' when lower(status) not in (\'active\',\'draft\') and sample_received_date is null and shoot_date is null then \'SAMPLE_NOT_RECEIVED\' when lower(status) not in (\'ready_to_dispatch\',\'ready_to_dispatch-MP\',\'active\',\'draft\') and sample_received_date is not null and shoot_date is null then \'SHOOT_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'ready_to_dispatch-MP\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is null then \'EDIT_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'ready_to_dispatch-MP\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null then \'CATALOG_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'ready_to_dispatch-MP\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and catalogix_received_timestamp is not null and CATALOGIX_SENT_TIMESTAMP is not null and inward_date is null then \'INWARD_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'ready_to_dispatch-MP\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and catalogix_received_timestamp is not null and CATALOGIX_SENT_TIMESTAMP is not null and inward_date is not null then \'QC\' else \'others\' end as final_status from main_data ), main_data3 as ( select *, case when sku_group like \'MP%\' and marketplace_cataloged_ts is not null then \'active\' else status end as status_mp_check from main_data2 ), metafields_pre as ( select SKU_GROUP, SAMPLE_RECEIVED_DATE, collection, LIVE_DATE,CREATED_AT_DATE, shopify_actual_inv, PHOTOSHOOT_STATUS, SHOOT_DATE,IMAGE_RECIEVED_DATE, EDITOR_OWNER, DELIVERY_DATE, date_of_entry, last_updated_at,DELIVERY_DATE_actual, date_of_entry_actual, last_updated_at_Actual, sample_dates, UNITS_ON_HAND, INWARD_DATE, PSLJ_STATUS,status_mp_check as STATUS, SR_LIVE_TAT, SHOOT_TAT, SHOOTDONE_EDITRECEIVED_TAT, EDIT_TAT, EDITDONE_CATALOGIXSENT_TAT, CATALOGIX_TAT, LIVE_TAT, FINAL_STATUS,wtw_tags,shoot_type, production_poc, production_creation_date,d2p_occassion, SAMPLE_DISPATCH_DATE_PRODUCTION, TRY_TO_DATE(edit_received_date, \'YYYY-MM-DD\') AS edit_received_date, TRY_TO_DATE(EDIT_COMPLETED_DATE, \'YYYY-MM-DD\') AS edit_completed_date, TRY_TO_DATE(CATALOGIX_SENT_TIMESTAMP,\'YYYY-MM-DD\') AS catalogix_sent_timestamp, TRY_TO_DATE(CATALOGIX_RECEIVED_TIMESTAMP,\'YYYY-MM-DD\') AS catalogix_received_timestamp from main_data3 ), sample_shoot_tracker AS ( SELECT sku_group, sample_shoot, SAMPLE_RECIEVED_DATE_to_shot, sample_returned_date_to_shoot, SAMPLE_OUT_FOR_SHOOT_DATE, shoot_post_remark FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY sample_shoot DESC NULLS LAST ) AS rn FROM ( SELECT UPPER(sku_group) AS sku_group, TRY_TO_DATE(sample_shoot, \'DD/MM/YYYY\') AS sample_shoot, TO_CHAR(TRY_TO_DATE(SAMPLE_RECIEVED_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS SAMPLE_RECIEVED_DATE_to_shot, TO_CHAR(TRY_TO_DATE(SAMPLE_RETURNED_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS sample_returned_date_to_shoot, TO_CHAR(TRY_TO_DATE(SAMPLE_OUT_FOR_SHOOT_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS SAMPLE_OUT_FOR_SHOOT_DATE, NULL shoot_post_remark FROM snitch_db.maplemonk.shoot_sample_tracker_Sheet1 UNION ALL SELECT UPPER(sku_group) as sku_group, sample_received_ts::DATE AS sample_shoot, NULL AS SAMPLE_RECIEVED_DATE_to_shot, NULL AS sample_returned_date_to_shoot, TO_CHAR(scheduled_shoot_ts, \'YYYY-MM-DD\') AS SAMPLE_OUT_FOR_SHOOT_DATE, shoot_post_remark FROM base_cte ) combined ) ranked_tracker WHERE rn = 1 ) select a.*, occassion_new, occassion, print_design, collar, product_tags, material_new, material, rise, pocket, sleeve_type, fit, color, closure, length, vendor, designs, style, sample_shoot, SAMPLE_RECIEVED_DATE_to_shot, sample_returned_date_to_shoot, SAMPLE_OUT_FOR_SHOOT_DATE, shoot_post_remark from metafields_pre a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group left join sample_shoot_tracker c on a.sku_group = c.sku_group where a.sku_group not like \'%_WBC\' ), im_deduped AS ( SELECT im.sku, im.sku_mapping || \'-\' || im.color AS sku_group, im.fit, im.sleeve, im.pattern, im.collar, im.closure, im.description, ROW_NUMBER() OVER (PARTITION BY im.sku_mapping || \'-\' || im.color ORDER BY im.sku) AS rn FROM snitch_db.maplemonk.logic_final_item_master im ), im_filtered AS ( SELECT * FROM im_deduped WHERE rn = 1 ) SELECT stl.*, im_filtered.fit AS FIT_item_master, im_filtered.sleeve AS SLEEVE_item_master, im_filtered.pattern AS PATTERN_item_master, im_filtered.collar AS COLLAR_item_master, im_filtered.closure AS CLOSURE_item_master, im_filtered.description AS DESCRIPTION_item_master FROM stl LEFT JOIN im_filtered ON stl.sku_group = im_filtered.sku_group where stl.sku_group not in (\'4MSFR0918\',\'4MSK8662-01\',\'4MSK8662-02\',\'4MSK8662-03\',\'4MSK8662-04\',\'4MSN1310-08\',\'4MSN1310-05\',\'4MSN1310-02\',\'4MST0218-03-T-SHIRT\',\'4MST0226-01-T-SHIRT\',\'4MTR0123-02\',\'4MTR0123-04\',\'4MSN1345-11-SHIRT\',\'4MSN1310-01-SHIRT\',\'4MSN1345-10-SHIRT\',\'4MSN1310-04-SHIRT\',\'4MSN1345-06-SHIRT\',\'4MSN1345-05-SHIRT\',\'4MSN1310-09-SHIRT\',\'4MSN1310-03-SHIRT\',\'4MSO3690-02\',\'4MTP0025-04\',\'4MSN1075-07-SHIRT\',\'4MST0224-01-T-SHIRT\',\'4MSN1310-10-SHIRT\',\'4MSS2142-16\',\'4MSS2142-11\',\'4MSS2648-5\',\'4MSS1813-25\',\'4MSS1813-24\',\'4MSS1813-16\',\'4MSS1813-17\',\'4MSS1813-11\',\'4MSS1813-26\',\'4MSS1813-12\',\'4MST2066-02\',\'4MSS3166-02\',\'4MSR5053-03\',\'4MSS1813-21\',\'4MSFR0929_T\',\'4MSFR0928_T\',\'4MSFR0927_T\',\'4MSFR0925_T\',\'4MSFR0926_T\',\'4MSD3516-04\',\'4MSD3516-02\',\'4MSS1203-18\',\'SH0038-03\',\'4MSFR0919\',\'4MSFR0920\',\'4MSFR0921\',\'4MSFR0922\',\'4MSFR0923\',\'4MSFR0924\',\'4MSS2304\',\'4MSS2651-04\',\'4MSS2651-02\',\'4MSS2651-07\',\'4MSS2651-05\',\'4MSS2651-01\',\'4MSS2651-06\',\'4MSS2651-03\',\'4MSO4505-02\',\'4MSO4505-01\',\'4MSR5062-02\',\'4MST0217-10\',\'4MSS2623- 01\',\'4MSS2623- 02\',\'4MSS2623- 04\',\'4MSS2935-03\',\'4MSS2935-04\',\'4MSS2935-01\',\'4MSS2935-02\',\'4MSD3703-06\',\'4MSS3302-2\',\'4MSS3302-1\',\'4MS04584-03\',\'4MBGSS1026-06\',\'4MSS3120\',\'4MST2343\',\'4MST2345\',\'4MSS3305\',\'4MSS3121\',\'4MSS3161\',\'4MST2344\',\'4MSW9899-01\',\'4MSW9898-01\',\'MPSS1001-02\',\'MPSS1001-03\',\'MPSS1001-01\',\'MPSS1001-06\',\'MPSS1001-05\',\'MP-SS1001-04\',\'MP-SS1001-06\',\'MP-SS1001-05\',\'MP-SS1001-02\',\'MP-SS1001-01\',\'MPSS1001-04\',\'MPSS1001-04\',\'MP-SS1006-02\',\'MP-SS1006-03\',\'MP-SS1002-01\',\'MP-SS1003-02\',\'MP-SS10